head.script:
scwin.trigger1_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "liteWindow",
        width: "700px",
        height: "600px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: false,
        useIFrame: false,
        closeAction: "closeAction",
        className: "test",
        scrollbars: true,
        resizable: false,
        menubar: true,
        pupUrl: "http://localhost:8080/test.html"
    };
    $w.openPopup("", options);
};
scwin.trigger2_onclick = function(e) {
    window.open("http://localhost:8080/test.html", "", "width=600, height=500, left=100, location=1");
};
scwin.select11_onblur = function(e) {
    //alert("블러");
};
scwin.select11_onchange = function() {
    //alert("체인지");
};
scwin.group1_onblur = function(e) {
    alert("1");
};
scwin.anchor1_onclick = function() {
    $w.showModal();
};
scwin.trigger3_onclick = function(e) {
    $w.showModal();
};
scwin.__checkErrLog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.__isCheck = function() {
    var date = new Date();
    var dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    var mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    var yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return WebSquare.wUnit.getJq("#wq_uuid_11_input").val() === today;
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 inputCalendar에서 날짜를 선택 후 selectbox의 값을 변경한다.
    //1. After running the sample, select the date in inputCalendar and change the value of selectbox.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'wq_uuid_11_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2calendar_selected')[0].click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById($p.id+'wq_uuid_11_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 날짜가 입력되고 selectbox값이 변경된다.
    //1. The date is entered and the value of the selectbox is changed.
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheck()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. The date is entered and the value of the selectbox is changed.
    //2. Click the '$ w.showModal ()' button and check the log.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 비활성화 처리되고 정상로그가 보여진다. (이전에는 로그오류 발생)
    //2. Deactivated and the normal log is displayed. (Previously a log error occurred)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#select11').hasClass('w2selectbox_disabled')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step  3. 콘솔창에서 $w.hideModal() 명령어를 실행후 로그를 확인한다.
    //3. Execute the $ w.hideModal () command in the console window and check the log.
    WebSquare.wUnit.addCommand("set", "$w.hideModal()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 화면이 활성화되고 정상로그가 보여진다.
    //3. The screen is activated and the normal log is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#select11').hasClass('w2selectbox_disabled')", "false");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    imports("uiplugin.popup");
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 06-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
